@page "/chat"
@using sv_352daf80febf4a0f84d76ed2581b1eb2.Services
@using sv_352daf80febf4a0f84d76ed2581b1eb2.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     SelectedChannelId="selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(threadOpen ? "" : "chat-main-expanded")">
        @if (selectedChannel is not null)
        {
            <div class="channel-header">
                <h5># @selectedChannel.Name</h5>
                <span class="channel-header-desc">@selectedChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="HandleScroll">
                @if (loadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @if (messages is not null)
                {
                    @foreach (var msg in messages)
                    {
                        <MessageItem Message="msg"
                                     ReplyCount="GetReplyCount(msg.Id)"
                                     OnOpenThread="OpenThread"
                                     OnReact="(emoji) => AddReaction(msg.Id, emoji)" />
                    }
                }
            </div>

            <MessageInput Placeholder="Message #@selectedChannel.Name" OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadOpen && threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel>? channels;
    private List<Message>? messages;
    private Channel? selectedChannel;
    private int selectedChannelId;
    private Dictionary<int, int> replyCountMap = new();

    // Thread state
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message>? threadReplies;

    // Pagination
    private const int PageSize = 30;
    private int currentSkip;
    private bool loadingMore;
    private bool hasMoreMessages = true;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels?.FirstOrDefault(c => c.Id == channelId);
        currentSkip = 0;
        hasMoreMessages = true;
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = null;

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        currentSkip = messages.Count;

        await BuildReplyCountMap();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        if (selectedChannel is not null)
        {
            var idx = channels!.FindIndex(c => c.Id == channelId);
            if (idx >= 0)
            {
                channels[idx] = selectedChannel with { UnreadCount = 0 };
            }
        }
    }

    private async Task HandleScroll()
    {
        // Triggered on scroll — in a real app, JS interop detects scroll-to-top.
        // Here we provide the mechanism for loading more.
    }

    public async Task LoadOlderMessages()
    {
        if (loadingMore || !hasMoreMessages || selectedChannel is null) return;

        loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId, currentSkip, PageSize);
        if (older.Count < PageSize)
        {
            hasMoreMessages = false;
        }

        messages = [..older, ..messages!];
        currentSkip += older.Count;
        loadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages ??= [];
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages?.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        var threadMessages = await ChatService.GetThreadAsync(messageId);
        threadReplies = threadMessages.Where(m => m.Id != messageId).ToList();
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = null;
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies ??= [];
        threadReplies.Add(reply);

        // Update reply count in main view
        replyCountMap[threadRootMessage.Id] = (replyCountMap.GetValueOrDefault(threadRootMessage.Id)) + 1;
    }

    private async Task AddReaction(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        // Optimistically update the local message
        var msg = messages?.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
    }

    private int GetReplyCount(int messageId) => replyCountMap.GetValueOrDefault(messageId);

    private async Task BuildReplyCountMap()
    {
        replyCountMap.Clear();
        if (messages is null) return;

        // Count messages that are replies to build thread indicators
        foreach (var msg in messages)
        {
            if (msg.ReplyToId.HasValue)
            {
                replyCountMap[msg.ReplyToId.Value] = replyCountMap.GetValueOrDefault(msg.ReplyToId.Value) + 1;
            }
        }
    }
}

