.chat-layout {
    display: flex;
    height: calc(100vh - 60px);
    overflow: hidden;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    border-right: 1px solid #dee2e6;
    overflow-y: auto;
